import Foundation

private struct AXID: Hashable {
    let e: AXUIElement
    static func == (l: AXID, r: AXID) -> Bool { CFEqual(l.e, r.e) }
    func hash(into h: inout Hasher) { h.combine(CFHash(e)) }
}

private enum AX {
    static func copy(_ e: AXUIElement, _ a: String) -> CFTypeRef? { var r: CFTypeRef?; return AXUIElementCopyAttributeValue(e, a as CFString, &r) == .success ? r : nil }
    static func string(_ e: AXUIElement, _ a: String) -> String? { copy(e,a) as? String }
    static func simple(_ e: AXUIElement, _ a: String = kAXValueAttribute) -> String? { guard let r=copy(e,a) else{return nil}; if let s=r as? String{return s}; if let n=r as? NSNumber{return n.stringValue}; return nil }
    static func bool(_ e: AXUIElement, _ a: String) -> Bool? { guard let r=copy(e,a) else{return nil}; if let b=r as? Bool{return b}; if let n=r as? NSNumber{return n.boolValue}; return nil }
    static func children(_ e: AXUIElement) -> [AXUIElement] { (copy(e,kAXChildrenAttribute) as? [AXUIElement] ?? []).filter{!CFEqual($0,e)} }
    static func actions(_ e: AXUIElement) -> [String] { var r:CFArray?; guard AXUIElementCopyActionNames(e,&r) == .success else{return []}; return r as? [String] ?? [] }
    static func settable(_ e: AXUIElement, _ a:String)->Bool { var b=DarwinBoolean(false); return AXUIElementIsAttributeSettable(e,a as CFString,&b) == .success && b.boolValue }
    static func set(_ e:AXUIElement,_ a:String,_ v:CFTypeRef)->AXError { AXUIElementSetAttributeValue(e,a as CFString,v) }
    static func press(_ e:AXUIElement)->AXError { AXUIElementPerformAction(e,kAXPressAction as CFString) }
}

private struct C { let path:String; let role:String?; let title:String?; let desc:String?; let value:String?; let valueDesc:String?; let enabled:Bool?; let selected:Bool?; let actions:[String] }
private struct R { let c:C; let e:AXUIElement }
private final class Walker {
    var seen:Set<AXID>=[]; var visited=0
    func all(_ root:AXUIElement)->[R]{ var stack:[(AXUIElement,Int,String)]=[(root,0,"app")],out:[R]=[]; while let (e,d,p)=stack.popLast(),visited<100000{let id=AXID(e:e);guard seen.insert(id).inserted else{continue};visited+=1;let role=AX.string(e,kAXRoleAttribute);out.append(R(c:C(path:p,role:role,title:AX.string(e,kAXTitleAttribute),desc:AX.string(e,kAXDescriptionAttribute),value:AX.simple(e),valueDesc:AX.simple(e,"AXValueDescription"),enabled:AX.bool(e,kAXEnabledAttribute),selected:AX.bool(e,kAXSelectedAttribute),actions:AX.actions(e)),e:e));if d<30{for(i,ch)in AX.children(e).enumerated().reversed(){stack.append((ch,d+1,"\(p)/\(AX.string(ch,kAXRoleAttribute) ?? "AXElement")[\(i)]"))}}};return out }
}

private func opt(_ n:String,_ a:[String])->String?{guard let i=a.firstIndex(of:n),i+1<a.count else{return nil};return a[i+1]}
private func norm(_ s:String?)->String{(s ?? "").trimmingCharacters(in:.whitespacesAndNewlines).lowercased()}
private func fields(_ c:C)->[String]{[c.title,c.desc,c.value,c.valueDesc].compactMap{$0}}
private func text(_ c:C)->String{fields(c).joined(separator:" ").lowercased()}
private func exact(_ c:C,_ q:String)->Bool{fields(c).contains{norm($0)==norm(q)}}
private func subtree(_ rs:[R],_ p:String)->[R]{rs.filter{$0.c.path==p || $0.c.path.hasPrefix(p+"/")}}
private func depth(_ p:String)->Int{p.filter{$0=="/"}.count}
private func parent(_ p:String)->String?{p.lastIndex(of:"/").map{String(p[..<$0])}}
private func app()->(NSRunningApplication,AXUIElement)?{guard AXIsProcessTrusted(),let a=NSRunningApplication.runningApplications(withBundleIdentifier:"com.apple.logic10").first else{return nil};return(a,AXUIElementCreateApplication(a.processIdentifier))}
private func scan()->[R]?{guard let(_,r)=app()else{return nil};return Walker().all(r)}
private func activate()->Bool{guard let(a,_)=app()else{return false};return a.activate(options:[.activateIgnoringOtherApps])}
private func key(_ code:CGKeyCode,_ flags:CGEventFlags=[]){guard let d=CGEvent(keyboardEventSource:nil,virtualKey:code,keyDown:true),let u=CGEvent(keyboardEventSource:nil,virtualKey:code,keyDown:false)else{return};d.flags=flags;u.flags=flags;d.post(tap:.cgAnnotatedSessionEventTap);usleep(45000);u.post(tap:.cgAnnotatedSessionEventTap)}
private func paste(_ s:String){NSPasteboard.general.clearContents();NSPasteboard.general.setString(s,forType:.string);key(9,.maskCommand)}
private func escape(){key(53)}
private func writeJSON(_ obj:Any,_ path:String?){guard let path,JSONSerialization.isValidJSONObject(obj),let d=try? JSONSerialization.data(withJSONObject:obj,options:[.prettyPrinted,.sortedKeys])else{return};try? d.write(to:URL(fileURLWithPath:path),options:.atomic)}

private func focusMain(){guard activate(),let rs=scan()else{return};if let w=rs.first(where:{$0.c.role==kAXWindowRole && norm($0.c.title).contains("tracks")}){if AX.settable(w.e,kAXFocusedAttribute){_=AX.set(w.e,kAXFocusedAttribute,kCFBooleanTrue)};if AX.settable(w.e,kAXMainAttribute){_=AX.set(w.e,kAXMainAttribute,kCFBooleanTrue)}};usleep(100000)}
private func windows(_ rs:[R])->[R]{rs.filter{$0.c.role==kAXWindowRole}}
private func saveWindows(_ rs:[R])->[R]{windows(rs).filter{norm($0.c.title).contains("save a copy as") || text($0.c).contains("save a copy as")}}
private func forbiddenModal(_ title:String)->Bool{let t=norm(title);return t.contains("save a copy as") || t.contains("open") || t.contains("import")}

private func modalStatus(_ out:String?)->Int32{guard let rs=scan()else{return 20};let ws=windows(rs).map{$0.c.title ?? $0.c.path};let sw=saveWindows(rs).map{$0.c.title ?? $0.c.path};writeJSON(["schema":"logic-coproducer-modal-status/1.0","windows":ws,"saveCopyWindows":sw],out);print("RESULT=PASS save_copy_windows=\(sw.count) windows=\(ws.count)");return 0}

private func dismissSave()->Int32{guard var rs=scan()else{return 20};var sw=saveWindows(rs);if sw.isEmpty{print("RESULT=PASS save_dialog_absent=true");return 0};guard sw.count==1 else{print("RESULT=RESTORE_FAIL reason=save-dialog-count-ambiguous count=\(sw.count)");return 30};let d=subtree(rs,sw[0].c.path);let cancels=d.filter{$0.c.role==kAXButtonRole && exact($0.c,"Cancel") && $0.c.enabled != false && $0.c.actions.contains(kAXPressAction as String)};guard cancels.count==1,AX.press(cancels[0].e)==.success else{print("RESULT=RESTORE_FAIL reason=save-dialog-cancel-not-unique count=\(cancels.count)");return 30};for _ in 0..<30{usleep(100000);rs=scan() ?? [];sw=saveWindows(rs);if sw.isEmpty{print("RESULT=PASS save_dialog_dismissed=true");return 0}};print("RESULT=RESTORE_FAIL reason=save-dialog-remained-after-cancel");return 30}

private func pressMenu(_ title:String)->Bool{guard let rs=scan()else{return false};let a=rs.filter{$0.c.role==kAXMenuItemRole && exact($0.c,title) && $0.c.enabled != false && $0.c.actions.contains(kAXPressAction as String)};return a.count==1 && AX.press(a[0].e)==.success}
private func waitSave()->R?{for _ in 0..<30{usleep(100000);if let rs=scan(){let a=saveWindows(rs);if a.count==1{return a[0]}}};return nil}
private func isInsideScroll(_ r:R,_ rs:[R],_ root:String)->Bool{var p=parent(r.c.path);while let q=p,q.hasPrefix(root){if let x=rs.first(where:{$0.c.path==q}),x.c.role==kAXScrollAreaRole{return true};p=parent(q)};return false}
private func filenameField(_ w:R,_ rs:[R])->R?{let d=subtree(rs,w.c.path);var a:[(R,Int)]=[];for r in d where r.c.role==kAXTextFieldRole && AX.settable(r.e,kAXValueAttribute) && !isInsideScroll(r,rs,w.c.path){var score=0;let v=(r.c.value ?? "").trimmingCharacters(in:.whitespacesAndNewlines);if !v.isEmpty{score+=8};if !v.contains("/"){score+=5};let rel=depth(r.c.path)-depth(w.c.path);if rel<=4{score+=6}else if rel<=7{score+=2};if text(r.c).contains("search"){score-=20};a.append((r,score))};a.sort{$0.1 == $1.1 ? $0.0.c.path<$1.0.c.path:$0.1>$1.1};guard let f=a.first,f.1>0 else{return nil};if a.count>1 && a[1].1==f.1{return nil};return f.0}
private func saveCopy(_ path:String)->Int32{focusMain();var ok=pressMenu("Save a Copy As…");if !ok{ok=pressMenu("Save a Copy As...")};guard ok,let _=waitSave()else{print("RESULT=SKIP reason=save-dialog-not-opened");return 10};guard let rs0=scan(),let w0=saveWindows(rs0).first,let field=filenameField(w0,rs0)else{let rc=dismissSave();print("RESULT=FAIL reason=save-name-field-not-resolved cleanup_rc=\(rc)");return rc==30 ? 30:20};let u=URL(fileURLWithPath:path),dir=u.deletingLastPathComponent().path,name=u.deletingPathExtension().lastPathComponent;guard AX.set(field.e,kAXValueAttribute,name as CFString)==.success else{let rc=dismissSave();print("RESULT=FAIL reason=save-name-write cleanup_rc=\(rc)");return rc==30 ? 30:20};key(5,[.maskShift,.maskCommand]);usleep(120000);paste(dir);key(36);usleep(300000);guard let rs1=scan(),let w1=saveWindows(rs1).first else{print("RESULT=RESTORE_FAIL reason=save-dialog-lost-after-folder-navigation");return 30};let buttons=subtree(rs1,w1.c.path).filter{$0.c.role==kAXButtonRole && exact($0.c,"Save") && $0.c.enabled != false && $0.c.actions.contains(kAXPressAction as String)};guard buttons.count==1,AX.press(buttons[0].e)==.success else{let rc=dismissSave();print("RESULT=FAIL reason=save-button-not-unique count=\(buttons.count) cleanup_rc=\(rc)");return rc==30 ? 30:20};for _ in 0..<50{usleep(100000);if let rs=scan(),saveWindows(rs).isEmpty{break}};guard let rsf=scan(),saveWindows(rsf).isEmpty else{print("RESULT=RESTORE_FAIL reason=save-dialog-remained-after-save");return 30};let fm=FileManager.default,cands=[path,path.hasSuffix(".logicx") ? path:path+".logicx",u.deletingPathExtension().appendingPathExtension("logicx").path];if let actual=cands.first(where:{fm.fileExists(atPath:$0)}){print("RESULT=PASS path=\(actual)");return 0};print("RESULT=FAIL reason=saved-copy-not-found modal_cleanup=verified");return 20}

private func targetStrips(_ label:String,_ rs:[R])->[R]{let raw=rs.filter{r in guard r.c.role==kAXLayoutItemRole || r.c.role==kAXGroupRole else{return false};let d=subtree(rs,r.c.path);return d.contains{exact($0.c,label)} && d.contains{$0.c.role==kAXSliderRole && text($0.c).contains("volume")} && d.contains{$0.c.role==kAXSliderRole && text($0.c).contains("pan")}};return raw.filter{x in !raw.contains{y in y.c.path != x.c.path && y.c.path.hasPrefix(x.c.path+"/")}}.sorted{depth($0.c.path)>depth($1.c.path)}}
@discardableResult private func selectTrack(_ label:String)->R?{guard activate(),let rs=scan()else{return nil};let ss=targetStrips(label,rs);guard !ss.isEmpty else{return nil};for s in ss{if AX.settable(s.e,kAXSelectedAttribute),AX.set(s.e,kAXSelectedAttribute,kCFBooleanTrue)==.success{usleep(150000);return s};for x in subtree(rs,s.c.path).filter({exact($0.c,label)}){if x.c.actions.contains(kAXPressAction as String),AX.press(x.e)==.success{usleep(150000);return s}}};return nil}
private func routeFingerprint(_ rs:[R])->[String]{let q=["st out","stereo out","no output","output","send","bus","input"];return rs.compactMap{r in let t=text(r.c);return q.contains(where:{t.contains($0)}) ? "\(r.c.path)|\(r.c.role ?? "")|\(fields(r.c).joined(separator:"~"))":nil}.sorted()}
private func menuContract(_ rs:[R])->Bool{rs.contains{$0.c.role==kAXMenuItemRole && exact($0.c,"No Output")} && rs.contains{$0.c.role==kAXMenuItemRole && exact($0.c,"Stereo Out")}}
private func routeCandidates(_ strip:R,_ rs:[R],_ value:String)->[R]{let d=subtree(rs,strip.c.path);var seen:Set<String>=[];var out:[R]=[];for hit in d where exact(hit.c,value){var p:String?=hit.c.path;while let q=p,q.hasPrefix(strip.c.path){if let r=rs.first(where:{$0.c.path==q}),r.c.enabled != false,r.c.actions.contains(kAXPressAction as String),seen.insert(q).inserted{out.append(r)};p=parent(q)}};return out.sorted{depth($0.c.path)>depth($1.c.path)}}
private func exactMenuPress(_ title:String)->Bool{guard let rs=scan()else{return false};let a=rs.filter{$0.c.role==kAXMenuItemRole && exact($0.c,title) && $0.c.enabled != false && $0.c.actions.contains(kAXPressAction as String)};return a.count==1 && AX.press(a[0].e)==.success}
private func qualifyingRouteControl(_ strip:R,_ rs:[R],_ display:String)->R?{var good:[R]=[];for c in routeCandidates(strip,rs,display){if AX.press(c.e) != .success{continue};usleep(120000);if let m=scan(),menuContract(m){good.append(c)};escape();usleep(100000)};return good.count==1 ? good[0]:nil}
private func outputRoundtrip(_ track:String,_ out:String?)->Int32{guard let s0=selectTrack(track),let rs0=scan(),let strip=targetStrips(track,rs0).first(where:{$0.c.path==s0.c.path}) ?? targetStrips(track,rs0).first else{print("RESULT=SKIP reason=track-not-resolved");return 10};let before=routeFingerprint(subtree(rs0,strip.c.path));guard let ctl=qualifyingRouteControl(strip,rs0,"St Out") ?? qualifyingRouteControl(strip,rs0,"Stereo Out") else{writeJSON(["schema":"logic-coproducer-a7-route-repair/1.0","result":"SKIP","before":before,"candidateCount":routeCandidates(strip,rs0,"St Out").count+routeCandidates(strip,rs0,"Stereo Out").count],out);print("RESULT=SKIP reason=no-unique-control-with-output-menu-contract");return 10};guard AX.press(ctl.e)==.success else{return 20};usleep(100000);guard exactMenuPress("No Output")else{escape();print("RESULT=FAIL reason=no-output-menu-selection");return 20};usleep(250000);guard let r1=scan(),let s1=targetStrips(track,r1).first else{print("RESULT=RESTORE_FAIL reason=track-lost-after-route-change");return 30};let changed=routeFingerprint(subtree(r1,s1.c.path));guard let restore=qualifyingRouteControl(s1,r1,"No Output")else{print("RESULT=RESTORE_FAIL reason=restore-output-control-not-resolved");return 30};guard AX.press(restore.e)==.success else{return 30};usleep(100000);guard exactMenuPress("Stereo Out")else{escape();print("RESULT=RESTORE_FAIL reason=stereo-out-restore-selection");return 30};usleep(250000);guard let rf=scan(),let sf=targetStrips(track,rf).first else{return 30};let final=routeFingerprint(subtree(rf,sf.c.path));writeJSON(["schema":"logic-coproducer-a7-route-repair/1.0","result":final==before ? "PASS":"RESTORE_FAIL","before":before,"changed":changed,"final":final],out);if final==before{print("RESULT=PASS route=\(track.replacingOccurrences(of:" ",with:"_")) changed=No_Output restored=Stereo_Out");return 0};print("RESULT=RESTORE_FAIL reason=route-fingerprint-mismatch");return 30}

private func tracksWindow(_ rs:[R])->R?{let a=windows(rs).filter{norm($0.c.title).contains("tracks")};return a.count==1 ? a[0]:a.first}
private func windowContains(_ w:R,_ rs:[R],_ needle:String)->Bool{subtree(rs,w.c.path).contains{fields($0.c).contains(where:{$0.contains(needle)})}}
private func tracksHas(_ name:String,_ expected:Bool)->Int32{guard let rs=scan(),let w=tracksWindow(rs)else{return 20};let has=windowContains(w,rs,name);print("RESULT=\(has==expected ? "PASS":"FAIL") tracks_contains=\(has ? "true":"false") filename=\(name)");return has==expected ? 0:20}
private func selectRegion(_ track:String,_ name:String)->Int32{guard selectTrack(track) != nil,let rs=scan(),let w=tracksWindow(rs)else{print("RESULT=SKIP reason=track-or-tracks-window");return 10};let d=subtree(rs,w.c.path);var a=d.filter{r in fields(r.c).contains(where:{$0.contains(name)}) && (r.c.role==kAXLayoutItemRole || r.c.role==kAXGroupRole || r.c.actions.contains(kAXPressAction as String))};a.sort{depth($0.c.path)>depth($1.c.path)};for r in a{if AX.settable(r.e,kAXSelectedAttribute),AX.set(r.e,kAXSelectedAttribute,kCFBooleanTrue)==.success{usleep(120000);print("RESULT=PASS region=\(name)");return 0};if r.c.actions.contains(kAXPressAction as String),AX.press(r.e)==.success{usleep(120000);print("RESULT=PASS region=\(name)");return 0}};print("RESULT=SKIP reason=region-not-selectable filename=\(name)");return 10}
private func strictSource(_ name:String,_ out:String?)->Int32{guard let rs=scan()else{return 20};var rows:[[String:Any]]=[];var qualified:[R]=[];for w in windows(rs){let title=w.c.title ?? "";let has=windowContains(w,rs,name);let d=subtree(rs,w.c.path);let editorText=d.contains{text($0.c).contains("audio file editor")};let titleEditor=norm(title).contains("audio file editor");let forbidden=forbiddenModal(title);let q=has && !forbidden && (editorText || titleEditor);rows.append(["title":title,"containsFilename":has,"editorSemantic":editorText || titleEditor,"forbiddenModal":forbidden]);if q{qualified.append(w)}};writeJSON(["schema":"logic-coproducer-a9-source-context-strict/1.0","filename":name,"windows":rows,"qualifiedWindows":qualified.map{$0.c.title ?? $0.c.path}],out);if qualified.count==1{print("RESULT=PASS mapping_level=associated_source_file_only filename=\(name) editor=\(qualified[0].c.title ?? "")");return 0};print("RESULT=SKIP reason=strict-audio-file-editor-context-not-unique count=\(qualified.count)");return 10}

private func openNestedMenu(_ parentTitle:String,_ childTitles:[String])->Bool{guard let rs=scan()else{return false};let p=rs.filter{$0.c.role==kAXMenuItemRole && exact($0.c,parentTitle) && $0.c.enabled != false && $0.c.actions.contains(kAXPressAction as String)};guard p.count==1,AX.press(p[0].e)==.success else{return false};usleep(120000);guard let r2=scan()else{return false};for t in childTitles{let c=r2.filter{$0.c.role==kAXMenuItemRole && exact($0.c,t) && $0.c.enabled != false && $0.c.actions.contains(kAXPressAction as String)};if c.count==1,AX.press(c[0].e)==.success{return true}};escape();return false}
private func importMusicXML(_ path:String)->Int32{focusMain();var opened=pressMenu("MusicXML…") || pressMenu("MusicXML...") || pressMenu("MusicXML");if !opened{opened=openNestedMenu("Import",["MusicXML…","MusicXML...","MusicXML"])};guard opened else{print("RESULT=SKIP reason=musicxml-menu-not-resolved");return 10};usleep(350000);key(5,[.maskShift,.maskCommand]);usleep(120000);paste(path);key(36);usleep(250000);key(36);usleep(650000);print("RESULT=PASS import_command_completed=true path=\(path)");return 0}

let a=Array(CommandLine.arguments.dropFirst());guard let cmd=a.first else{exit(2)};guard AXIsProcessTrusted(),app() != nil else{exit(3)};let out=opt("--out",a)
switch cmd {
