case "dismiss-save-dialog": exit(dismissSave())
case "save-copy": guard let p=opt("--path",a) else{exit(2)};exit(saveCopy(p))
case "output-roundtrip": guard let t=opt("--track",a) else{exit(2)};exit(outputRoundtrip(t,out))
case "tracks-has": guard let n=opt("--filename",a),let p=opt("--present",a) else{exit(2)};exit(tracksHas(n,p=="yes" || p=="true"))
case "select-region": guard let t=opt("--track",a),let n=opt("--name",a) else{exit(2)};exit(selectRegion(t,n))
case "source-context": guard let n=opt("--filename",a) else{exit(2)};exit(strictSource(n,out))
